"""Reference context workflow in the existing Studio shell."""
from tubeforge.api.studio_shell import STUDIO_STATIC_MENU_SCRIPT,wrap_studio_page

MAIN='''<main class="shell"><div class="studio-page-head"><div><h1>Reference videos</h1><p>Capture a video's context for an original Short or long-form video. This step does not copy footage, verify claims or generate a script.</p></div></div>
<div class="reference-grid">
<section class="panel reference-form"><h2>Capture a reference</h2>
<form id="referenceForm"><label for="referenceUrl">Public YouTube link</label><input id="referenceUrl" type="url" placeholder="https://www.youtube.com/watch?v=…" required maxlength="2000">
<div class="reference-fields"><div><label for="referenceTarget">Our video length</label><select id="referenceTarget"><option value="30">Short · 30s</option><option value="60" selected>Short · 60s</option><option value="90">Short · 90s</option><option value="105">Short · 105s</option><option value="120">Short · 120s</option><option value="600">10 minutes</option><option value="720">12 minutes</option><option value="900">15 minutes</option></select></div><div><label for="referenceLanguage">Caption language</label><input id="referenceLanguage" value="en" required maxlength="35" placeholder="en or hi"></div></div>
<label for="referenceFocus">What should the AI focus on? (optional)</label><textarea id="referenceFocus" maxlength="500" rows="2" style="min-height:64px;height:64px" placeholder="For example: the claim that it is 8x faster, and what it costs you; ignore the sponsor read."></textarea>
<label for="referenceChannel">Channel identity</label><select id="referenceChannel"><option value="default">default</option></select>
<div class="actions"><button id="captureReference" type="submit">Capture reference</button></div><p id="referenceNotice" role="status" aria-live="polite"></p></form>
<p class="reference-meta">Public metadata and captions only. No video download or AI call. Missing captions can be supplied after capture.</p></section>
<section class="panel reference-history"><h2>Capture history</h2><p id="historyNotice" role="status" class="reference-meta">Loading saved references…</p><ul id="referenceList" class="reference-list"></ul><button type="button" id="reloadReferences" class="secondary">Refresh history</button></section>
<section id="referenceDetail" class="panel reference-detail" aria-label="Reference details"><p id="detailNotice" class="reference-error" role="status"></p>
<div id="emptyReference"><h2>No reference selected</h2><p class="reference-meta">Paste a public link to capture its title and transcript, or open a saved reference.</p></div>
<div id="selectedReference" hidden><span id="referenceState" class="reference-state keep"></span><h2 id="referenceTitle" class="reference-title keep"></h2><div class="actions keep"><button id="collapseReference" type="button" class="secondary small" aria-expanded="true" aria-controls="selectedReference">Minimize</button></div><p id="referenceMeta" class="reference-meta"></p><p><a id="referenceSource" target="_blank" rel="noopener noreferrer">Open original video</a> · <a id="downloadReference">Download captured context</a></p><p><a id="prepareLongForm" hidden>Prepare long-form script</a></p>
<details id="prepareShort" hidden><summary>Prepare an original Short</summary><p class="reference-meta">Watch the original, then describe its visual style. TubeForge captured text only and has not inspected its visuals. A new Short uses fresh narration and independent source research; source footage is not copied.</p><form id="shortForm"><label for="shortTopic">Topic</label><input id="shortTopic" maxlength="500" required><label for="shortAngle">Your angle</label><input id="shortAngle" maxlength="1000" required><label for="shortUse">How to use the transcript</label><select id="shortUse"><option value="fresh">Write fresh narration (the transcript is only context)</option><option value="improve">Use it as a draft and let the AI make it better</option><option value="exact">Use it exactly as the script</option></select><label for="shortTake">Your own take (optional)</label><textarea id="shortTake" maxlength="1500" style="min-height:72px;height:72px" placeholder="For example: the speaker says X, but I want to say Y instead, because …"></textarea><p class="reference-meta">Your take outranks the reference: where they disagree, the Short follows you.</p><label for="shortThumb">Thumbnail guidance (optional)</label><textarea id="shortThumb" maxlength="1000" style="min-height:64px;height:64px" placeholder="What should the thumbnail say and show? For example: the number 8x in big yellow type, the speaker looking shocked."></textarea><label for="shortStyle">Visual style you observed</label><textarea id="shortStyle" maxlength="1500" required placeholder="For example: close-up hands, quick cuts, large captions"></textarea><label><input type="checkbox" id="shortWatched" required> I watched this exact reference and described its visual style.</label><label><input type="checkbox" id="shortConfirm" required> Queue independent research and a new script for review. This may use the configured writer allowance.</label><button type="submit" id="createShort">Create Short job</button><p id="shortNotice" role="status" aria-live="polite"></p></form></details>
<p id="referenceFocusNote" class="reference-meta" hidden></p><label for="referenceRevision">Revision</label><select id="referenceRevision" aria-label="Reference revision"></select><p id="referenceMessage" role="status" aria-live="polite"></p><ul id="referenceLimitations" class="reference-limitations"></ul>
<div class="actions"><button id="refreshReference" type="button" class="secondary">Capture fresh revision</button><button id="cancelReference" type="button" class="secondary">Cancel pending capture</button><button id="deleteReference" type="button" class="secondary">Delete reference</button></div>
<details id="editInputs"><summary>Edit inputs and capture again</summary><p class="reference-meta">Change what the AI should focus on, the length, caption language or channel, then capture a fresh revision. The link stays the same; earlier revisions are kept.</p><div class="reference-fields"><div><label for="editTarget">Our video length</label><select id="editTarget"><option value="30">Short · 30s</option><option value="60">Short · 60s</option><option value="90">Short · 90s</option><option value="105">Short · 105s</option><option value="120">Short · 120s</option><option value="600">10 minutes</option><option value="720">12 minutes</option><option value="900">15 minutes</option></select></div><div><label for="editLanguage">Caption language</label><input id="editLanguage" maxlength="35" required></div></div><label for="editFocus">What should the AI focus on? (optional)</label><textarea id="editFocus" maxlength="500" rows="2" style="min-height:64px;height:64px"></textarea><label for="editChannel">Channel identity</label><select id="editChannel"></select><div class="actions"><button id="saveEdits" type="button">Save changes and capture again</button></div><p id="editNotice" role="status" aria-live="polite"></p></details>
<h3>Transcript</h3><p id="transcriptSummary" class="reference-meta"></p><div id="referenceTranscript" class="reference-transcript" tabindex="0" aria-label="Captured transcript"></div>
<details id="supplyTranscript"><summary>Supply a transcript</summary><p class="reference-meta">Paste the transcript as ordinary text (timestamps are not needed; they are estimated from the video length), or SRT, VTT or a JSON cue list. A text file works too (up to 1 MB). Saving creates a new revision and preserves the earlier capture.</p>
<label for="transcriptFile">Transcript file (optional)</label><input id="transcriptFile" type="file" accept=".txt,.srt,.vtt,.json,text/plain,application/json">
<label for="transcriptText">Transcript text</label><textarea id="transcriptText" spellcheck="false" placeholder="Paste what is said in the video, as plain text."></textarea><div class="actions"><button id="saveTranscript" type="button">Save transcript revision</button></div><p id="transcriptNotice" role="status" aria-live="polite"></p></details>
<details id="referenceBrief"><summary>Proposed improvement brief</summary><p id="briefSummary" class="reference-meta"></p><ol id="briefProposals" class="reference-limitations"></ol><p id="briefLimitations" class="reference-meta"></p></details>
<details><summary>Activity</summary><ol id="referenceActivity" class="reference-activity"></ol></details></div></section></div></main>'''
SCRIPT=r'''
(()=>{
const $=id=>document.getElementById(id), labels={pending:'Capture pending',ready:'Context captured',needs_input:'Transcript needed',failed:'Capture failed'};
let selected=null,revision=null,current=null,lastSignature='',listSignature='',busy=false,selectionLoading=false,detailRequest=0,shortAvailable=false;const drafts=new Map();
const csrf=()=>decodeURIComponent((document.cookie.match(/(?:^|; )tubeforge_csrf=([^;]+)/)||[])[1]||'');
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'content-type':'application/json','x-csrf-token':csrf(),...(options.headers||{})}});if(response.status===401){location.assign('/login');throw Error('Sign in again.');}if(!response.ok){let detail='Request failed.';try{const body=await response.json();detail=typeof body.detail==='string'?body.detail:'Check the request fields.';}catch(_){}throw Error(detail);}return response.json();}
function say(id,message,error=false){$(id).textContent=message;$(id).classList.toggle('reference-error',error);}
function controls(){const pending=current?.intake.state==='pending',latest=current?.is_latest;const disabled=busy||selectionLoading||!latest||current?.intake.intake_id!==selected; $('captureReference').disabled=busy;$('createShort').disabled=disabled||!shortAvailable;$('refreshReference').disabled=disabled||pending;$('saveEdits').disabled=disabled||pending;$('deleteReference').disabled=busy||selectionLoading||current?.intake.intake_id!==selected;$('cancelReference').disabled=disabled||!pending;$('saveTranscript').disabled=disabled||pending;}
function choose(id,rev=null){if(selected)drafts.set(selected,$('transcriptText').value);if(selected!==id){$('transcriptText').value=drafts.get(id)||'';$('supplyTranscript').open=false;say('transcriptNotice','');}selected=id;revision=rev;current=null;selectionLoading=true;lastSignature='';controls();say('detailNotice','Loading selected reference…');return loadDetail();}
function clock(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0');}
function show(detail){const signature=JSON.stringify(detail);current=detail;selectionLoading=false;if(signature===lastSignature){controls();return;}lastSignature=signature;const v=detail.intake,s=v.snapshot;
$('emptyReference').hidden=true;$('selectedReference').hidden=false;$('referenceState').textContent=labels[v.state];$('referenceState').dataset.state=v.state;
$('referenceTitle').textContent=s?.title||'Reference '+v.request.reference_url.split('v=')[1];$('referenceSource').href=v.request.reference_url;
$('referenceMeta').textContent=s?`${s.creator} · ${clock(s.duration_seconds)} source duration · ${s.language} · ${s.transcript_origin.replaceAll('_',' ')} · captured ${new Date(s.captured_at).toLocaleString()}${detail.cache_hit?' · reused saved capture':''}`:'Waiting for the worker to retrieve public metadata and captions.';
$('downloadReference').hidden=!s;$('downloadReference').href=`/api/reference-intakes/${v.intake_id}/snapshot?revision=${v.revision}`;
$('prepareLongForm').hidden=v.state!=='ready'||v.request.target_duration_seconds<600;
const editKey=v.intake_id+':'+v.revision;if($('editInputs').dataset.key!==editKey){$('editInputs').dataset.key=editKey;$('editTarget').value=String(v.request.target_duration_seconds);$('editLanguage').value=v.request.language;$('editFocus').value=v.request.focus||'';const ch=$('editChannel');if(!ch.options.length)for(const o of [...$('referenceChannel').options])ch.add(new Option(o.text,o.value));ch.value=v.request.channel_identity;say('editNotice','');}
const shortKey=v.intake_id+':'+v.revision+':'+(v.reference_snapshot_sha256||'');if($('prepareShort').dataset.key!==shortKey){$('prepareShort').dataset.key=shortKey;$('prepareShort').open=false;$('shortForm').reset();$('shortTopic').value=s?.title||'';$('shortAngle').value=v.request.focus||'';say('shortNotice',shortAvailable?'':'Short preparation is unavailable: configure independent research and a reference-Short preset.',!shortAvailable);}{const note=$('referenceFocusNote');note.hidden=!v.request.focus;note.textContent=v.request.focus?'Your focus: '+v.request.focus:'';}$('prepareShort').hidden=v.state!=='ready'||v.request.target_duration_seconds>=600||!detail.is_latest;$('prepareLongForm').href='/long-form?intake='+v.intake_id+'&revision='+v.revision;
$('referenceRevision').replaceChildren(...detail.revisions.map(r=>{const option=document.createElement('option');option.value=r.revision;option.textContent=`Revision ${r.revision} · ${labels[r.state]}`;option.selected=r.revision===v.revision;return option;}));
$('referenceMessage').textContent=v.message||(v.state==='ready'?'Transcript context is available. Factual research and script review come next.':v.state==='pending'?'Queued or being captured by the worker. This is not a generation approval.':'');
$('referenceLimitations').replaceChildren(...(s?.limitations||[]).map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));
const cues=s?.cues||[];$('transcriptSummary').textContent=cues.length?`${cues.length} timestamped cues. Text is reference material, not approved narration.`:'No usable transcript captured yet.';
const transcriptKey=JSON.stringify(cues);if($('referenceTranscript').dataset.signature!==transcriptKey){$('referenceTranscript').dataset.signature=transcriptKey;$('referenceTranscript').replaceChildren(...cues.map(c=>{const p=document.createElement('p');p.className='reference-cue';const time=document.createElement('time'),span=document.createElement('span');time.textContent=clock(c.start_seconds);span.textContent=c.text;p.append(time,span);return p;}));}
const brief=detail.observation_brief;$('briefSummary').textContent=brief?`${brief.classification} ${brief.cue_count} cues; caption intervals cover ${brief.caption_interval_coverage_percent}% of the source duration. Coverage is not completeness or accuracy.`:'Capture a reference before proposing improvements.';
$('briefProposals').replaceChildren(...(brief?.proposed_improvements||[]).map(item=>{const li=document.createElement('li'),a=document.createElement('a'),quote=document.createElement('p'),question=document.createElement('p'),change=document.createElement('p'),evidence=document.createElement('p');a.href=v.request.reference_url+'&t='+Math.floor(item.start_seconds);a.target='_blank';a.rel='noopener noreferrer';a.textContent=`${clock(item.start_seconds)} · ${item.label} · cue ${item.cue_index+1}`;quote.textContent='Source excerpt: '+item.source_excerpt;question.textContent='Review question: '+item.viewer_question;change.textContent='Proposed change: '+item.proposed_change;evidence.textContent=item.supporting_evidence+' '+item.planned_scene;li.append(a,quote,question,change,evidence);return li;}));$('briefLimitations').textContent=(brief?.limitations||[]).join(' ');
$('referenceActivity').replaceChildren(...detail.activity.map(event=>{const li=document.createElement('li');li.textContent=`${event.event.replaceAll('_',' ')} · ${event.actor} · ${new Date(event.created_at).toLocaleString()}`;return li;}));controls();}
async function loadDetail(){if(!selected)return;const id=selected,rev=revision,token=++detailRequest;try{const detail=await api(`/api/reference-intakes/${id}${rev?'?revision='+rev:''}`);if(selected!==id||revision!==rev||token!==detailRequest)return;show(detail);say('detailNotice','');}catch(error){if(selected!==id||revision!==rev||token!==detailRequest)return;say('detailNotice','Could not refresh this reference. '+error.message,true);}}
async function loadHistory(){try{const response=await api('/api/reference-intakes');const sig=JSON.stringify(response.items.map(d=>[d.intake.intake_id,d.intake.revision,d.intake.state,d.intake.snapshot?.title]));if(sig!==listSignature){listSignature=sig;$('referenceList').replaceChildren(...response.items.map(detail=>{const v=detail.intake,li=document.createElement('li'),button=document.createElement('button'),name=document.createElement('strong'),state=document.createElement('span');button.type='button';button.setAttribute('aria-current',String(v.intake_id===selected));name.textContent=v.snapshot?.title||v.request.reference_url;state.className='reference-meta';state.textContent=`${labels[v.state]} · revision ${v.revision} · ${v.request.target_duration_seconds<600?v.request.target_duration_seconds+" sec":v.request.target_duration_seconds/60+" min"} target`;button.append(name,state);button.onclick=()=>{listSignature='';choose(v.intake_id);loadHistory();};li.append(button);return li;}));}say('historyNotice',response.items.length?'Latest '+response.items.length+' saved references.':'No references captured yet.');if(!selected&&response.items.length)await choose(response.items[0].intake.intake_id);}catch(error){say('historyNotice','Could not refresh history. '+error.message,true);}}
$('shortForm').onsubmit=async event=>{event.preventDefault();if(busy||selectionLoading||!current||!current.is_latest)return;const v=current.intake,key=v.intake_id+':'+v.revision+':'+(v.reference_snapshot_sha256||'');if($('prepareShort').dataset.key!==key||v.state!=='ready')return;busy=true;controls();$('createShort').disabled=true;say('shortNotice','Creating a Short job…');try{const result=await api(`/api/reference-intakes/${v.intake_id}/short`,{method:'POST',body:JSON.stringify({expected_revision:v.revision,reference_snapshot_sha256:v.reference_snapshot_sha256,topic:$('shortTopic').value,angle:$('shortAngle').value,visual_observations:$('shortStyle').value,watched_reference:$('shortWatched').checked,confirmed_queue:$('shortConfirm').checked,transcript_use:$('shortUse').value,my_take:$('shortTake').value.trim()||null,thumbnail_guidance:$('shortThumb').value.trim()||null})});if(selected!==v.intake_id||$('prepareShort').dataset.key!==key)return;say('shortNotice',result.reused?'Existing Short job found; no new research or writer attempt was queued.':'Short job created. Research and script review happen in Generations; no approval has been granted.');const link=document.createElement('a');link.href='/#generations';link.textContent=' Open Generations';$('shortNotice').append(link);}catch(error){if(selected===v.intake_id&&$('prepareShort').dataset.key===key)say('shortNotice',error.message,true);}finally{busy=false;controls();}};
$('referenceForm').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;controls();say('referenceNotice','Saving the intake request…');try{const detail=await api('/api/reference-intakes',{method:'POST',body:JSON.stringify({reference_url:$('referenceUrl').value,target_duration_seconds:Number($('referenceTarget').value),language:$('referenceLanguage').value,channel_identity:$('referenceChannel').value,focus:$('referenceFocus').value.trim()||null})});await choose(detail.intake.intake_id,detail.intake.revision);say('referenceNotice',detail.intake.state==='pending'?'Reference saved and queued for capture.':'Existing reference returned; no new capture was queued.');await loadHistory();if(innerWidth<1000)$('referenceDetail').scrollIntoView({block:'start'});}catch(error){say('referenceNotice',error.message,true);}finally{busy=false;controls();}};
async function revise(action,edits){if(busy||selectionLoading||!current||current.intake.intake_id!==selected||!current.is_latest)return;const id=selected,selectedRevision=revision,expected=current.intake.revision;busy=true;controls();const place=action==='transcript'?'transcriptNotice':'detailNotice';say(place,'Saving the revision request…');try{const value={expected_revision:expected,action};if(action==='transcript')value.transcript_text=$('transcriptText').value;if(edits)value.edits=edits;const detail=await api(`/api/reference-intakes/${id}/revisions`,{method:'POST',body:JSON.stringify(value)});if(selected===id&&revision===selectedRevision){detailRequest++;revision=detail.intake.revision;lastSignature='';show(detail);say(place,action==='cancel'?'Pending capture cancelled.':'New revision saved and queued; earlier revisions are preserved.');}await loadHistory();}catch(error){if(selected===id&&revision===selectedRevision)say(place,error.message,true);}finally{busy=false;controls();}}
$('refreshReference').onclick=()=>revise('refresh');
$('saveEdits').onclick=()=>{const edits={focus:$('editFocus').value.trim(),language:$('editLanguage').value.trim(),target_duration_seconds:Number($('editTarget').value),channel_identity:$('editChannel').value};if(!edits.language){say('editNotice','Enter a caption language.',true);return;}say('editNotice','');revise('refresh',edits);};
$('deleteReference').onclick=async()=>{if(!current||busy)return;const id=current.intake.intake_id,name=$('referenceTitle').textContent;if(!confirm('Delete the saved reference "'+name+'" and all its captures? Videos already made from it are not affected.'))return;busy=true;controls();try{await api('/api/reference-intakes/'+id,{method:'DELETE'});selected=null;revision=null;current=null;lastSignature='';$('selectedReference').hidden=true;$('emptyReference').hidden=false;say('detailNotice','Reference deleted.');await loadHistory();}catch(error){say('detailNotice','Could not delete: '+error.message,true);}finally{busy=false;controls();}};
function setCollapsed(on){$('selectedReference').classList.toggle('collapsed',on);$('collapseReference').textContent=on?'Expand':'Minimize';$('collapseReference').setAttribute('aria-expanded',String(!on));try{localStorage.setItem('tubeforge.reference.collapsed',on?'1':'0')}catch(_){}}
$('collapseReference').onclick=()=>setCollapsed(!$('selectedReference').classList.contains('collapsed'));
try{if(localStorage.getItem('tubeforge.reference.collapsed')==='1')setCollapsed(true)}catch(_){}$('cancelReference').onclick=()=>revise('cancel');$('saveTranscript').onclick=()=>revise('transcript');$('referenceRevision').onchange=()=>{revision=Number($('referenceRevision').value);current=null;selectionLoading=true;lastSignature='';controls();loadDetail();};
$('transcriptFile').onchange=async()=>{const file=$('transcriptFile').files[0];if(!file)return;if(file.size>1000000){say('transcriptNotice','Transcript file exceeds 1 MB.',true);return;}$('transcriptText').value=await file.text();say('transcriptNotice','File read locally. Save to create a transcript revision.');};
$('reloadReferences').onclick=()=>{loadHistory();loadDetail();};api('/api/reference-intakes/options').then(options=>{shortAvailable=Boolean(options.short_preparation_available);if(options.default_transcript_use)$('shortUse').value=options.default_transcript_use;if(!shortAvailable)say('shortNotice',options.short_preparation_reason||'Short preparation is unavailable.',true);controls();$('referenceChannel').replaceChildren(...options.channels.map(channel=>{const o=document.createElement('option');o.value=channel;o.textContent=channel;return o;}));}).catch(error=>say('referenceNotice','Could not load channel choices. '+error.message,true));
const deepLink=new URLSearchParams(location.search),deepId=deepLink.get('intake'),deepRev=Number(deepLink.get('revision'));
if(/^[a-f0-9]{32}$/.test(deepId||'')&&Number.isSafeInteger(deepRev)&&deepRev>0)choose(deepId,deepRev);
loadHistory();setInterval(()=>{if(!document.hidden){loadHistory();loadDetail();}},2500);
})();
'''


def render_reference_html(username=None):
    content=wrap_studio_page('references',username,'Reference videos',MAIN)
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reference videos · TubeForge</title><style>#selectedReference.collapsed>:not(.keep){display:none}.reference-grid{display:grid;align-items:start;gap:20px;grid-template-columns:minmax(280px,340px) minmax(0,1fr)}.reference-form{grid-column:1;grid-row:1}.reference-history{grid-column:1;grid-row:2}.reference-detail{grid-column:2;grid-row:1/3}@media (max-width:1000px){.reference-grid{grid-template-columns:1fr}.reference-form,.reference-history,.reference-detail{grid-column:auto;grid-row:auto}.reference-form{order:1}.reference-detail{order:2}.reference-history{order:3}}</style></head><body>'+content+'<script>'+SCRIPT+STUDIO_STATIC_MENU_SCRIPT+'</script></body></html>'
